{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "What is Period Mode in Lunora?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Period Mode is the part of the Lunora app that follows your menstrual cycle alongside your prayer, Quran and dhikr. It tracks your cycle and estimates the next period, explains what changes in worship during menstruation, offers duas and dhikr that fit your mood, and counts qada fasts. Lunora is available on iPhone and Android."
            }
        },
        {
            "@type": "Question",
            "name": "Does Lunora follow the four madhhabs?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Lunora shows the views of the Hanafi, Shafi'i, Maliki and Hanbali schools rather than a single answer. Its Period guide lists each school's view on reading the Quran during menstruation together with the source, and shows your school first if you have chosen one. The app does not issue rulings and suggests asking a scholar about your own situation."
            }
        },
        {
            "@type": "Question",
            "name": "Can Lunora track the fasts I need to make up after my period?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Period Mode asks about period days that fell in Ramadan, and the Qada screen shows how many fasts are recorded, kept and remaining. You can pick a day for your next qada fast and get a reminder the evening before. Lunora only counts the days; when and how to make them up depends on your madhhab."
            }
        },
        {
            "@type": "Question",
            "name": "What happens to the adhan and Protect My Prayer during my period?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "While Period Mode is on, the adhan sound is turned off and Protect My Prayer rests without asking. Both return on their own when your period ends, and period days do not break your prayer streak."
            }
        },
        {
            "@type": "Question",
            "name": "Is my period data private?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Your period, mood, symptom and journal records stay on your device in its secure storage and are not uploaded to Lunora's servers. No account is needed and there are no ads."
            }
        },
        {
            "@type": "Question",
            "name": "Does Period Mode work during pregnancy or after giving birth?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. You can set your situation to pregnant, postpartum, breastfeeding or irregular. The estimate adapts or pauses accordingly, and postpartum mode counts the days until you mark that your bleeding has stopped."
            }
        }
    ]
}

