{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "Namazımı Koru nedir?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Namazımı Koru, Lunora uygulamasındaki bir özelliktir. Namaz vakti girince seçtiğiniz uygulamalar kısa bir süre, varsayılan olarak 15 dakika bekler. Lunora'da “Kıldım”a dokunduğunuzda hemen açılırlar ve namaz, namaz takibinizde işaretlenir."
            }
        },
        {
            "@type": "Question",
            "name": "Uygulamalar ne kadar süre kilitli kalır?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Varsayılan olarak vaktin girişinden itibaren 15 dakika. Android'de 10, 15 ya da 20 dakika, iPhone'da 15 ya da 20 dakika seçebilirsiniz. “Kıldım” derseniz hemen açılırlar; demezseniz süre dolunca kendiliğinden açılırlar."
            }
        },
        {
            "@type": "Question",
            "name": "Acil bir durumda uygulamayı açabilir miyim?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Evet. “Acil bir durum mu? Şimdi kaldır”a dokunduğunuzda uygulamalar hemen açılır ve bir sonraki vakitte yeniden korunur. Telefon uygulaması ve Lunora hiçbir zaman beklemez."
            }
        },
        {
            "@type": "Question",
            "name": "Namazımı Koru iPhone'da çalışıyor mu?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Evet. iPhone'da Apple'ın Ekran Süresi iznini kullanır ve iOS 16 veya sonrasını gerektirir. Android'de Kullanım erişimi ile diğer uygulamaların üzerinde gösterme iznini kullanır."
            }
        },
        {
            "@type": "Question",
            "name": "Âdet günlerimde ne olur?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Dönem Modu açıkken Namazımı Koru kendiliğinden dinlenir ve dönem bitince geri döner. Size sormaz; seçtiğiniz uygulamalar ve vakitler yerinde kalır, dönem günleri namaz serinizi de bozmaz."
            }
        },
        {
            "@type": "Question",
            "name": "Namazımı Koru ücretsiz mi?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Lunora, iPhone ve Android'de ücretsiz indirilir ve reklam içermez. Beş vaktin tamamında Namazımı Koru, ücretsiz denemeyle başlayabileceğiniz Lunora+ aboneliğiyle gelir."
            }
        }
    ]
}

