{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "Was ist „Mein Gebet schützen“?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "„Mein Gebet schützen“ ist eine Funktion der App Lunora. Wenn eine Gebetszeit beginnt, warten die Apps, die du gewählt hast, eine kurze Zeit, standardmäßig 15 Minuten. Wenn du in Lunora auf „Ich habe gebetet“ tippst, öffnen sie sich sofort, und das Gebet wird in deinem Gebetsprotokoll markiert."
            }
        },
        {
            "@type": "Question",
            "name": "Wie lange bleiben die Apps gesperrt?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Standardmäßig 15 Minuten, gerechnet ab Beginn der Gebetszeit. Auf Android kannst du 10, 15 oder 20 Minuten wählen, auf dem iPhone 15 oder 20. Tippst du auf „Ich habe gebetet“, öffnen sie sich sofort; wenn nicht, öffnen sie sich von selbst, sobald die Zeit um ist."
            }
        },
        {
            "@type": "Question",
            "name": "Kann ich in einem Notfall eine App öffnen?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Ja. Tippe auf „Ein Notfall? Jetzt aufheben“, und die Apps öffnen sich sofort; beim nächsten Gebet sind sie wieder geschützt. Die Telefon-App und Lunora müssen nie warten."
            }
        },
        {
            "@type": "Question",
            "name": "Funktioniert „Mein Gebet schützen“ auf dem iPhone?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Ja. Auf dem iPhone nutzt die Funktion Apples Bildschirmzeit-Berechtigung und braucht iOS 16 oder neuer. Auf Android nutzt sie den Nutzungszugriff und die Berechtigung, über anderen Apps angezeigt zu werden."
            }
        },
        {
            "@type": "Question",
            "name": "Was passiert während meiner Periode?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "„Mein Gebet schützen“ ruht von selbst, solange der Periodenmodus an ist, und kommt zurück, wenn deine Periode endet. Die Funktion fragt dich nicht, deine gewählten Apps und Gebete bleiben erhalten, und Periodentage unterbrechen deine Gebetsserie nicht."
            }
        },
        {
            "@type": "Question",
            "name": "Ist „Mein Gebet schützen“ kostenlos?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Lunora kannst du kostenlos für iPhone und Android herunterladen, und es gibt keine Werbung. „Mein Gebet schützen“ für alle fünf Gebete gibt es mit Lunora+, einem Abo, das du mit einem Gratis-Test beginnen kannst."
            }
        }
    ]
}

