{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "Qu’est-ce que Protéger ma prière ?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Protéger ma prière est une fonctionnalité de l’application Lunora. Quand l’heure d’une prière arrive, les applications que tu as choisies attendent un court moment, 15 minutes par défaut. Quand tu touches « J’ai prié » dans Lunora, elles s’ouvrent aussitôt et la prière est marquée dans ton suivi des prières."
            }
        },
        {
            "@type": "Question",
            "name": "Combien de temps les applications restent-elles bloquées ?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "15 minutes par défaut, à compter du début de l’heure de la prière. Sur Android, tu peux choisir 10, 15 ou 20 minutes, et sur iPhone 15 ou 20. Si tu touches « J’ai prié », elles s’ouvrent immédiatement ; sinon, elles s’ouvrent toutes seules à la fin du délai."
            }
        },
        {
            "@type": "Question",
            "name": "Puis-je ouvrir une application en cas d’urgence ?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Oui. Touche « Une urgence ? Lève-la maintenant » et les applications s’ouvrent tout de suite ; elles sont de nouveau protégées à la prière suivante. L’app Téléphone et Lunora n’attendent jamais."
            }
        },
        {
            "@type": "Question",
            "name": "Protéger ma prière fonctionne-t-il sur iPhone ?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Oui. Sur iPhone, la fonctionnalité utilise l’autorisation Temps d’écran d’Apple et nécessite iOS 16 ou une version ultérieure. Sur Android, elle utilise l’accès à l’utilisation et l’autorisation d’affichage par-dessus les autres applications."
            }
        },
        {
            "@type": "Question",
            "name": "Que se passe-t-il pendant mes règles ?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Protéger ma prière se met en pause tout seul tant que le Mode règles est activé et revient à la fin de tes règles. Il ne te demande rien, tes applications et prières choisies sont conservées, et les jours de règles ne cassent pas ta série de prières."
            }
        },
        {
            "@type": "Question",
            "name": "Protéger ma prière est-il gratuit ?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Lunora est gratuite à télécharger sur iPhone et Android, et sans publicité. Protéger ma prière pour les cinq prières est inclus dans Lunora+, un abonnement que tu peux commencer par un essai gratuit."
            }
        }
    ]
}

