{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "Does Lunora have a khatam (hatim) tracker?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Lunora has three khatam plans: Ramadan khatam (30 days, one juz a day), khatam in 60 days (about ten pages a day) and khatam in a year (one to two pages a day). The app shows which day of the plan you are on and how much of it is done."
            }
        },
        {
            "@type": "Question",
            "name": "Can I make my own Quran reading plan?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Choose the surahs you want, add a name and an icon if you like, then read one surah a day, two a day, or set the number of days yourself. A day may then hold more than one surah."
            }
        },
        {
            "@type": "Question",
            "name": "How do I mark a day as read?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Open the day's reading from the plan, read it in Lunora's Quran reader and tap “I've read it”. The day is marked as done and the plan moves on to the next one."
            }
        },
        {
            "@type": "Question",
            "name": "What happens to my reading plan during my period?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "If Period Mode is on, Lunora leaves the choice to you: pause the plan or continue. While it is paused the day count does not advance, and it carries on from the same day when you turn Period Mode off. The plan also links to the Period Mode guide, which lists the views of the four madhhabs on reading the Quran during menstruation."
            }
        },
        {
            "@type": "Question",
            "name": "Which mushaf layout does Lunora use?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "The page view follows the page layout of the Madinah mushaf, 604 pages, and the 60-day and one-year khatam plans give their daily readings as page ranges of that mushaf. Translation and transliteration are available in list view."
            }
        },
        {
            "@type": "Question",
            "name": "Is Lunora available on iPhone and Android?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Lunora has no ads. Lunora+ is a subscription that unlocks the full app, and you can start it with a free trial."
            }
        }
    ]
}

