{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "Hat Lunora einen Khatm-Tracker (Hatim)?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Ja. Lunora hat drei Khatm-Pläne: Ramadan-Khatm (30 Tage, ein Juz pro Tag), Khatm in 60 Tagen (etwa zehn Seiten pro Tag) und Khatm in einem Jahr (ein bis zwei Seiten pro Tag). Die App zeigt, an welchem Tag des Plans du bist und wie viel davon geschafft ist."
            }
        },
        {
            "@type": "Question",
            "name": "Kann ich meinen eigenen Koran-Leseplan erstellen?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Ja. Wähle die Suren, die du möchtest, füge nach Wunsch einen Namen und ein Symbol hinzu und lies dann eine Sure pro Tag, zwei pro Tag, oder leg die Anzahl der Tage selbst fest. Ein Tag kann dann mehr als eine Sure enthalten."
            }
        },
        {
            "@type": "Question",
            "name": "Wie markiere ich einen Tag als gelesen?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Öffne die Lesung des Tages aus dem Plan, lies sie in Lunoras Koran-Leseansicht und tippe auf „Gelesen“. Der Tag wird als erledigt markiert, und der Plan geht zum nächsten Tag weiter."
            }
        },
        {
            "@type": "Question",
            "name": "Was passiert mit meinem Leseplan während meiner Periode?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Wenn der Periodenmodus an ist, überlässt Lunora dir die Wahl: den Plan pausieren oder weitermachen. Solange er pausiert ist, rückt die Tageszählung nicht vor, und wenn du den Periodenmodus ausschaltest, geht es am selben Tag weiter. Der Plan verlinkt außerdem auf den Periodenratgeber, der die Ansichten der vier Rechtsschulen zum Koranlesen während der Menstruation aufführt."
            }
        },
        {
            "@type": "Question",
            "name": "Welches Mushaf-Layout verwendet Lunora?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Die Seitenansicht folgt dem Seitenlayout des Medina-Mushafs mit 604 Seiten, und die Khatm-Pläne für 60 Tage und ein Jahr geben ihre täglichen Lesungen als Seitenbereiche dieses Mushafs an. Übersetzung und Umschrift gibt es in der Listenansicht."
            }
        },
        {
            "@type": "Question",
            "name": "Gibt es Lunora für iPhone und Android?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Lunora kannst du kostenlos aus dem App Store und von Google Play herunterladen, und es gibt keine Werbung. Lunora+ ist ein Abo, das die ganze App freischaltet, und du kannst es mit einem Gratis-Test beginnen."
            }
        }
    ]
}

