{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "Can I count dhikr from my home screen without opening the app?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Add Lunora's “Tesbih with count” widget and tap + Count or the ring. Each tap is counted on the widget and added to your daily count in the app. On iPhone this needs iOS 17 or later; on earlier versions a tap opens the counter instead."
            }
        },
        {
            "@type": "Question",
            "name": "Which dhikr can I count on the widget?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "The widget first shows the dhikr you last counted in the app, then six everyday phrases: SubhanAllah, Alhamdulillah, Allahu Akbar, La ilaha illallah, Astaghfirullah and Allahumma salli ala Muhammad. Tap the phrase to move to the next one."
            }
        },
        {
            "@type": "Question",
            "name": "Does Lunora show where each dhikr comes from?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Every entry in Lunora's dhikr library lists its source, for example a hadith number from Bukhari or Muslim, together with the Arabic text, a transliteration and the meaning."
            }
        },
        {
            "@type": "Question",
            "name": "Does Lunora include the 99 Names of Allah (Asmaul Husna)?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. You can read the 99 Names with short meanings, count through them one by one in order, and add a “Name of the day” widget. The app notes that the hadith about Allah's ninety-nine names is sahih, while the list of names itself was compiled by scholars."
            }
        },
        {
            "@type": "Question",
            "name": "Can I keep making dhikr during my period?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Dhikr and dua remain available on period days. When Period Mode is on, the Dhikr screen also links to the Period Mode guide, which sets out the views of the four madhhabs on reading the Quran during menstruation."
            }
        },
        {
            "@type": "Question",
            "name": "Is Lunora available on iPhone and Android?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Lunora has no ads. Lunora+ is a subscription that unlocks the full app, and you can start it with a free trial."
            }
        }
    ]
}

