{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "Kann ich Dhikr auf dem Startbildschirm zählen, ohne die App zu öffnen?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Ja. Füge das Lunora-Widget „Tasbih mit Zähler“ hinzu und tippe auf + Zählen oder auf den Ring. Jeder Tipp wird im Widget gezählt und zu deinem Tageszähler in der App addiert. Auf dem iPhone braucht das iOS 17 oder neuer; bei älteren Versionen öffnet ein Tipp stattdessen den Zähler."
            }
        },
        {
            "@type": "Question",
            "name": "Welchen Dhikr kann ich im Widget zählen?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Das Widget zeigt zuerst den Dhikr, den du zuletzt in der App gezählt hast, dann sechs alltägliche Formeln: SubhanAllah, Alhamdulillah, Allahu Akbar, La ilaha illallah, Astaghfirullah und Allahumma salli ala Muhammad. Tippe auf die Formel, um zur nächsten zu wechseln."
            }
        },
        {
            "@type": "Question",
            "name": "Zeigt Lunora, woher jeder Dhikr stammt?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Ja. Jeder Eintrag in der Dhikr-Bibliothek von Lunora nennt seine Quelle, zum Beispiel eine Hadith-Nummer aus Bukhari oder Muslim, zusammen mit dem arabischen Text, einer Umschrift und der Bedeutung."
            }
        },
        {
            "@type": "Question",
            "name": "Enthält Lunora die 99 Namen Allahs (Asma ul Husna)?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Ja. Du kannst die 99 Namen mit kurzen Bedeutungen lesen, sie einzeln der Reihe nach durchzählen und ein Widget „Name des Tages“ hinzufügen. Die App weist darauf hin, dass der Hadith über die neunundneunzig Namen Allahs sahih ist, die Liste der Namen selbst aber von Gelehrten zusammengestellt wurde."
            }
        },
        {
            "@type": "Question",
            "name": "Kann ich während meiner Periode weiter Dhikr machen?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Ja. Dhikr und Duas bleiben an Periodentagen verfügbar. Wenn der Periodenmodus an ist, verlinkt der Dhikr-Bildschirm außerdem auf den Periodenratgeber, der die Ansichten der vier Rechtsschulen zum Koranlesen während der Menstruation darlegt."
            }
        },
        {
            "@type": "Question",
            "name": "Gibt es Lunora für iPhone und Android?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Lunora kannst du kostenlos aus dem App Store und von Google Play herunterladen, und es gibt keine Werbung. Lunora+ ist ein Abo, das die ganze App freischaltet, und du kannst es mit einem Gratis-Test beginnen."
            }
        }
    ]
}

