{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "What is Lunora?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Lunora is an Islamic app designed for Muslim women. It brings prayer times, the Quran, duas, dhikr and a Period Mode into one app, on iPhone and Android. It works offline, has no ads and needs no account."
            }
        },
        {
            "@type": "Question",
            "name": "What is Period Mode?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Period Mode follows your cycle alongside your prayer, Quran and dhikr. You can track your cycle and see predictions, read hadith and fiqh guidance from all four madhhabs and a ghusl guide, get dua and dhikr suggestions that fit your mood, and count your qada fasts. Prayer reminders go quiet on your period days, and your period records stay on your device."
            }
        },
        {
            "@type": "Question",
            "name": "Is Lunora available on iPhone and Android?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Lunora is available on the App Store for iPhone and on Google Play for Android phones."
            }
        },
        {
            "@type": "Question",
            "name": "Is Lunora free?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Lunora has no ads. In most countries the full app is unlocked with Lunora+, a subscription you can start with a 7-day free trial. Lunora+ includes every reciter, the offline Quran, the full Quran Course and Hifz, Protect My Prayer for all five prayers and the large widgets."
            }
        },
        {
            "@type": "Question",
            "name": "Which languages does Lunora support?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "English, Turkish, Arabic, French, German, Indonesian, Malay, Urdu and Bengali."
            }
        },
        {
            "@type": "Question",
            "name": "Is my data private?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Your period, mood, symptom and journal records, notes and saved duas stay on your device and are not uploaded to our servers. No account is needed and there are no ads. To fix crashes and improve the app, we collect anonymous usage and crash data with Firebase Analytics and Crashlytics, and your city and country are used to calculate prayer times. We never sell your data. See our Privacy Policy for details."
            }
        }
    ]
}

{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "Lunora nedir?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Lunora, Müslüman kadınlar için tasarlanmış bir İslami uygulamadır. Namaz vakitlerini, Kur'an'ı, duayı, zikri ve Dönem Modu'nu tek uygulamada buluşturur; iPhone ve Android'de ücretsizdir. Çevrimdışı çalışır, reklam yoktur, hesap açmanız gerekmez."
            }
        },
        {
            "@type": "Question",
            "name": "Dönem Modu nedir?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Dönem Modu, namazınızın, Kur'an'ın ve zikrin yanında döngünüzü de takip eder. Döngünüzü gün gün izleyip tahminleri görebilir, dört mezhebin hadis ve fıkıh rehberini ve gusül rehberini okuyabilir, ruh hâlinize uygun dua ve zikir önerileri alabilir, kaza oruçlarınızı sayabilirsiniz. Dönem günlerinde namaz hatırlatıcıları sessize geçer; dönem kayıtlarınız yalnızca cihazınızda kalır."
            }
        },
        {
            "@type": "Question",
            "name": "Lunora iPhone ve Android'de var mı?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Evet. Lunora, iPhone için App Store'da, Android telefonlar için Google Play'de indirilebilir."
            }
        },
        {
            "@type": "Question",
            "name": "Lunora ücretsiz mi?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Lunora'yı indirmek ücretsizdir ve reklam yoktur. Çoğu ülkede uygulamanın tamamı Lunora+ aboneliğiyle açılır; 7 gün ücretsiz deneyerek başlayabilirsiniz. Lunora+ satın alınamayan ülkelerde uygulama ücretsiz kullanılır. Lunora+ tüm kârileri, çevrimdışı Kur'an'ı, Kur'an Kursu ve Hafızlık'ın tamamını, beş vakitte Namazımı Koru'yu ve büyük widget'ları kapsar."
            }
        },
        {
            "@type": "Question",
            "name": "Lunora hangi dillerde?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Türkçe, İngilizce, Arapça, Fransızca, Almanca, Endonezce, Malayca, Urduca ve Bengalce."
            }
        },
        {
            "@type": "Question",
            "name": "Verilerim gizli mi?",
